const TRIVIA_PACK = [];
const TRIVIA_ARTICLES = {};
function readBank(text) {
 let source, category, page;
 for (const line of text.trim().split('\n').map(s=>s.trim()).filter(Boolean)) {
  if (line.startsWith('@')) { [source, category, page] = line.slice(1).split('|'); TRIVIA_ARTICLES[source] = page; continue; }
  const [difficulty,q,correct,...rest] = line.split('|');
  const answers = [correct,...rest.slice(0,3)], explanation = rest[3];
  if (!source || answers.length!==4 || !explanation || rest.length!==4) throw new Error('Malformed authored trivia: '+line);
  TRIVIA_PACK.push({source,category,difficulty:({e:'easy',m:'medium',h:'hard'})[difficulty],q,answers,correct:0,explanation,
   citations:page==='ShambConkins rules'?[]:[{label:page,url:'https://en.wikipedia.org/wiki/'+encodeURIComponent(page.replace(/ /g,'_'))}],
   provenance:'authored; linked for review; not live verified'});
 }
}
readBank(COMEDY);
readBank(FILMS);
readBank(CULT_AND_HORROR);
readBank(GAMES);
readBank(MUSIC);
readBank(ANIME_AND_NICK);
readBank(PLACES_AND_EXTRAS);
for(const q of TRIVIA_PACK){
 if(q.source==='“2 Player Games: The Challenge”')q.citations=[{label:'2 Player Games: The Challenge — JindoBlu',url:'https://play.google.com/store/apps/details?id=com.JindoBlu.TwoPlayerGamesChallenge'}];
 if(q.q.includes('classic Hang in There poster'))q.citations=[{label:'Hang in there, Baby — the original poster',url:'https://en.wikipedia.org/wiki/Hang_in_there,_Baby'}];
 if(q.q.startsWith('What was Nickelodeon Gak'))q.citations=[{label:'Nickelodeon Gak',url:'https://en.wikipedia.org/wiki/Nickelodeon_Gak'}];
}
function installTriviaPack(catalog) {
 const existing=new Set(catalog.trivia.map(q=>q.source+'|'+q.q));
 for(const q of TRIVIA_PACK)if(!existing.has(q.source+'|'+q.q)){catalog.trivia.push(q);existing.add(q.source+'|'+q.q);}
}

Object.assign(exports,{TRIVIA_PACK,TRIVIA_ARTICLES,installTriviaPack});